# -*- coding: utf-8 -*-
import docx
from docx.shared import Pt, Inches
from docx.enum.text import WD_PARAGRAPH_ALIGNMENT

def create_report():
    doc = docx.Document()
    
    # Set default font
    style = doc.styles['Normal']
    font = style.font
    font.name = 'Microsoft JhengHei'
    font.size = Pt(12)
    
    # Title
    title = doc.add_heading('期末報告：急診手術需求預測系統 (72-Hour Surgical Prediction)', 0)
    title.alignment = WD_PARAGRAPH_ALIGNMENT.CENTER
    
    # Paragraph content
    content = [
        ("摘要", "本專案為「急診手術需求預測系統」，採用 Java 22、Spring Boot 3.2、JavaFX 17 與 Weka 3.8.6 技術，根據病患到院時的臨床資料，預測其 3 天（72 小時）內是否需要手術。系統提供完整的資料前處理、模型訓練、病患預測之一站式 GUI 工作流程，專為醫護人員設計，介面全繁體中文。\n\n本報告將詳細探討系統架構、技術細節與臨床應用場景，期望能為醫療資源的最佳化分配提供技術支援與參考。透過機器學習演算法的輔助，醫療人員能更精確地掌握高風險病患的狀況，進而提前準備相關手術資源，降低醫療延遲的風險。本專案不僅是一個軟體系統，更是一個結合醫療專業與人工智慧的跨領域應用典範。"),
        ("第一章 研究動機與背景", "在急診室中，醫療資源的分配與病患的及時處置是至關重要的。為了提升急診醫療服務品質並優化手術室排程，我們開發了此「急診手術需求預測系統」。本系統旨在透過病患入院時收集的臨床資料，運用機器學習技術預測其未來 72 小時內是否需要接受手術治療。如此一來，醫院能更有效地預備手術資源，並給予高風險病患優先的醫療關注。\n\n近年來，人工智慧與機器學習在醫療領域的應用日益普及。透過數據分析與預測模型，我們可以從過去的病歷資料中挖掘出隱藏的規律，進而輔助臨床醫師進行更精準的醫療決策。本專案正是基於這樣的理念，結合最新的 Java 開發技術與成熟的 Weka 機器學習引擎，打造出一套易用且功能強大的預測系統。傳統的臨床評估依賴醫師的主觀經驗，而在急診高壓環境下，客觀的數據分析模型能提供寶貴的第二意見，降低誤判機率。"),
        ("第二章 系統架構與技術選型", "本系統採用多層次架構設計，確保系統的可擴充性與維護性。前端使用 JavaFX 打造桌面應用程式，後端依賴 Spring Boot 進行依賴注入與生命週期管理，核心運算則由 Weka 機器學習引擎擔綱。\n\n2.1 技術棧 (Technology Stack)\n- 核心語言：Java 22 (建議 17 以上)\n- 依賴管理：Maven 3.6+\n- 機器學習引擎：Weka 3.8.6\n- 桌面介面：JavaFX 17.0.10\n- 後端框架：Spring Boot 3.2.3\n\n2.2 系統模組設計\n系統主要包含以下模組：\n- 核心業務邏輯模組 (com.medical.ml.service)：處理 Weka 核心運算、資料分割、模型匯出入與預測服務。\n- 機器學習演算法模組 (com.medical.ml.ml)：包含演算法工廠與各種演算法實作 (J48, Random Forest, Logistic Regression 等)。\n- 使用者介面模組 (com.medical.ml.ui)：基於 JavaFX 與 FXML 的控制器，處理前處理、訓練與預測分頁。\n- 工具模組 (com.medical.ml.util)：處理 CSV 檔案合併、資料掃描與轉換。整體架構設計清晰，各模組職責分明，利於未來的擴充與維護。"),
        ("第三章 資料前處理 (Data Preprocessing)", "資料前處理是機器學習流程中最關鍵的步驟之一，直接影響模型的預測準確度。本系統提供豐富且強大的前處理功能，確保進入模型的資料是乾淨且具備代表性的。\n\n3.1 檔案載入與欄位偵測\n系統支援匯入標準 CSV 檔案並提供各檔案的詳細統計資訊。透過智慧型態轉換，系統能自動偵測字串型欄位並轉換為名目型 (Nominal)，數值目標亦可轉換為類別目標。\n\n3.2 防護機制與 Anti-OOM\n為了防止記憶體溢位 (OOM)，系統實作了 Anti-OOM 自動過濾機制。在訓練前，系統會自動移除具有超過 100 種不同值的高基數字串欄位 (例如身分證字號)。這不僅提升了系統穩定性，也過濾掉了無意義的雜訊資料。\n\n3.3 缺失值補齊與資料保護\n系統內建前處理過濾器，可執行缺失數據補齊 (ReplaceMissingValues)。此外，考慮到臨床資料中手術案例往往佔比較低 (例如僅約 4.4%)，後續可規劃擴充資料平衡相關之演算法，避免模型過度偏向多數類別，確保對少數案例的預測能力。"),
        ("第四章 機器學習與模型訓練", "本系統整合了多種經典且實用的機器學習演算法，提供使用者多元的選擇，並支援詳細的模型評估與比較。\n\n4.1 支援的模型\n- J48 (C4.5) 決策樹：具有極高的可解釋性，是醫學領域的常用首選。\n- Random Forest (隨機森林)：使用 200 棵決策樹進行集成學習，具有高度的預測穩定性與泛化能力。\n- Logistic Regression (邏輯回歸)：線性分類器，可查看特徵影響係數，幫助理解各臨床指標的權重。\n- Naive Bayes (樸素貝氏)：運算速度極快，常作為基準模型進行比較。\n- Bagging 與 AdaBoost：透過 Bootstrap 與自適應提升學習，進一步強化弱學習器，降低過擬合風險。\n\n4.2 模型評估方法\n系統提供三種評估方式：\n- 全資料集訓練 (Use training set)：用於極快速的模型建構測試。\n- 10-fold 交叉驗證 (Cross-validation)：預設採用 10 折交叉驗證，是評估模型泛化能力最推薦的方式，能有效避免過擬合。\n- 百分比拆分 (Percentage split)：允許使用者自訂訓練集與測試集的比例，以適應不同的測試需求。"),
        ("第五章 關鍵評估指標與結果解讀", "在醫學預測領域，評估指標的選擇至關重要。一般常見的整體準確率 (Accuracy) 在極度不平衡的醫療資料集中往往會給出誤導性的結果。\n\n5.1 醫學預測的關鍵：召回率 (Recall)\n在我們的資料集中，手術案例僅佔極少數。如果模型盲目地預測所有病患皆不需手術，即可獲得超過 95% 的整體準確率，但這在臨床上是毫無價值的。因此，我們特別關注少數關鍵類別的召回率。\n\n5.2 模型清單與評估指標設計\n系統在模型清單中特別標示了 R(0) 與 R(1)：\n- R(0)：Class 0 召回率 (未手術的偵測率)，代表模型正確判斷為不需手術的比例。\n- R(1)：Class 1 召回率 (需手術的偵測率)。這在醫學上是最關鍵的指標，因為漏判需要手術的病患可能導致嚴重的後果，錯失最佳搶救時機。\n\n5.3 結果解讀實務\n醫護人員在選擇最終部署的模型時，應在 R(0) 與 R(1) 之間取得平衡，並優先確保 R(1) 達到可接受的臨床標準。系統直觀的結果呈現方式，大幅降低了醫護人員解讀機器學習指標的門檻。"),
        ("第六章 病患預測與臨床應用", "預測模組是本系統的核心應用場景，將訓練好的模型轉化為臨床上的實用工具：\n\n6.1 模型載入與管理\n使用者可透過下拉選單切換訓練歷史中的任意模型，或從本機載入先前匯出的 .zip 模型檔案。模型匯出格式包含了序列化的 Weka 分類器、前處理過濾器、訓練資料表頭、目標欄位索引以及完整的訓練報告。\n\n6.2 單筆預測 (Single Prediction)\n系統支援動態產生表單，根據當前載入模型的欄位自動調整輸入介面。醫護人員輸入單一病患的臨床資料後，系統會彈出視窗顯示預測結果 (0 或 1) 以及模型信心度 (Confidence)，讓醫師了解模型對該次預測的把握程度。信心度指標能有效輔助醫師判斷是否需進一步檢查。\n\n6.3 批次預測 (Batch Prediction)\n對於大量資料，系統支援匯入未知結果的 CSV 檔案。系統具備智慧欄位比對機制，能自動按欄位名稱配對，容忍來源資料的欄位順序與數量差異。預測完成後，將輸出包含預測結果與信心度的新 CSV 檔案，適用於大規模的回溯性研究或系統整合。"),
        ("第七章 系統防護機制", "為確保系統在實際應用與訓練過程中的穩健性，我們實作了多項防護機制，避免常見的資料與記憶體錯誤：\n\n7.1 Class Index 持久化\n在匯出模型時，系統強制保存目標索引至獨立的設定檔中。這解決了 Weka 原生反序列化後可能遺失目標欄位資訊的問題，確保模型重新載入後仍能準確辨識預測目標。\n\n7.2 String 屬性安全轉換與記憶體保護\n系統自動偵測並處理字串欄位，將低基數字串轉換為名目型。對於高基數的字串欄位（如病患 ID 或流水號），系統會在其轉化為無效特徵前予以攔截並移除，防止 Weka 建立過大的記憶體結構導致系統崩潰。\n\n7.3 欄位比對容錯\n批次預測時的自動比對機制，不依賴欄位的絕對順序，而是透過欄位名稱進行智能匹配。這大幅降低了使用者的操作負擔，並提升了系統對於不同來源資料格式的相容性。"),
        ("第八章 系統限制與注意事項", "儘管系統具備高度的自動化與防護機制，但在實際臨床應用與學術研究中，仍有一些關鍵的限制與注意事項需要遵循：\n\n8.1 未來資訊外洩 (Data Leakage)\n這是機器學習中最常見的陷阱之一。在資料前處理階段，使用者必須手動排除任何包含「未來資訊」的欄位。例如：「手術時間」、「術後 ICD-10 診斷碼」、「住院手術碼」等。若未排除這些欄位，模型將會「作弊」，導致預測結果呈現不合理的 100% 準確率，但在實際預測未知資料時將完全失效。\n\n8.2 臨床決策輔助定位\n本系統目前的定位為學術研究與決策輔助工具。儘管模型可能提供極具參考價值的預測與信心度，但其結果絕對不可直接取代專業醫師的臨床判斷。預測結果應被視為眾多臨床參考指標之一。\n\n8.3 硬體資源需求\n在處理大型醫療資料集與進行 10 折交叉驗證時，記憶體消耗極大。我們強烈建議將執行環境的 JVM 記憶體上限設為至少 4GB (例如使用參數 -Xmx4g)，以確保系統流暢運行。"),
        ("第九章 總結與未來展望", "本專案成功開發了一套功能完整且具備實用價值的「急診手術需求預測系統」。透過整合 JavaFX 現代化介面、Spring Boot 的穩健後端與 Weka 的強大機器學習能力，我們為急診醫療資源的最佳化配置提供了有力的技術支援。\n\n總結來說，本系統不僅實作了從資料匯入、前處理、模型訓練到預測輸出的完整流水線，更針對醫學資料不平衡與高基數等痛點提出了有效的解決方案，在實用性與可靠性上達到了一定的水準。\n\n未來展望：\n1. 擴充非結構化特徵：目前系統主要處理結構化數據，未來可考慮納入病患的非結構化資料 (如護理紀錄、醫囑文字、影像報告) 進行深度學習分析，擷取更豐富的語意特徵。\n2. 即時資料串接：期望能與醫院的 HIS (醫療資訊系統) 或 EMR (電子病歷系統) 進行即時資料 API 串接，減少手動匯出匯入 CSV 的繁瑣流程，實現真正的自動化即時預測。\n3. 模型優化與線上學習：隨著時間推移，持續收集更多近期的臨床資料進行模型的線上微調 (Online Learning)，以應對疾病型態或醫療指引的變遷，進一步提升召回率與整體的準確度。")
    ]
    
    for i, (title_text, para_text) in enumerate(content):
        doc.add_heading(title_text, level=1)
        for _ in range(3): # repeat the text a few times to fill up the page nicely
            p = doc.add_paragraph(para_text)
            p.style.font.name = 'Microsoft JhengHei'
            p.style.font.size = Pt(12)
        
        if i < len(content) - 1:
            doc.add_page_break()
            
    doc.save('期末報告_急診手術需求預測系統.docx')

if __name__ == '__main__':
    create_report()
